
const LOGO=`<svg width="34" height="34" viewBox="0 0 40 40" aria-hidden="true"><path fill="#174D3C" d="M8 4h24a6 6 0 016 6v17a6 6 0 01-6 6H21l-9 6v-6H8a6 6 0 01-6-6V10a6 6 0 016-6z"/><path fill="#F7F4EB" fill-rule="evenodd" d="M14 10h8a5.5 5.5 0 010 11h-3v5h-5zM19 14v3h3a1.5 1.5 0 000-3z"/><circle cx="34" cy="8" r="4" fill="#EF795F"/></svg>`;
// ---- CONTEÚDO: "título#nota#it|pt;it|pt" ----
const ITALIAN_COURSE=[
["Primeiros contatos","Cumprimentos, despedidas e cortesia",[
`Cumprimentos#"Ciao" serve para oi e tchau, só com amigos. "Buongiorno" usa-se até o início da tarde. Pronúncia: "ci" soa "tchi" (ciao = tchau).#Ciao|Oi / tchau;Buongiorno|Bom dia;Buonasera|Boa tarde / boa noite;Buonanotte|Boa noite (ao dormir);Come stai?|Como você está?;Sto bene, grazie|Estou bem, obrigado(a)`,
`Despedidas#"Arrivederci" é a despedida padrão. "A presto" = até breve. Cultura: na Itália é comum desejar "Buona giornata" ao sair de lojas.#Arrivederci|Até logo;A presto|Até breve;A domani|Até amanhã;Ci vediamo|A gente se vê;Buona giornata|Tenha um bom dia;Buon viaggio|Boa viagem`,
`Cortesia#"Prego" significa "de nada", mas também "fique à vontade". "Scusi" é a forma educada; "scusa" é informal.#Per favore|Por favor;Grazie mille|Muito obrigado;Prego|De nada;Scusi|Com licença;Mi dispiace|Sinto muito;Non c'è problema|Não tem problema`]],
["Apresentações","Nome, origem, nacionalidade e pronomes",[
`Nome#"Mi chiamo Luca" = literalmente "eu me chamo Luca". É a forma natural de se apresentar. "ti" é informal; "si" é formal.#Mi chiamo Luca|Eu me chamo Luca;Come ti chiami?|Como você se chama?;Come si chiama?|Como o senhor se chama?;Piacere|Prazer;Molto piacere|Muito prazer;Sono Marta|Eu sou a Marta`,
`Origem#Nacionalidades terminam em -o (masculino) ou -a (feminino). "Di" indica a cidade; "dal" o país masculino.#Sono brasiliano|Sou brasileiro;Sono brasiliana|Sou brasileira;Di dove sei?|De onde você é?;Sono di Recife|Sou de Recife;Vengo dal Brasile|Venho do Brasil;Sei italiano?|Você é italiano?`,
`Pronomes#Em italiano o pronome costuma ser omitido: "Sono stanco". "Lei" também é a forma de respeito ("o senhor/a senhora").#Io sono|Eu sou;Tu sei|Tu és / você é;Lui è|Ele é;Lei è|Ela é;Noi siamo|Nós somos;Loro sono|Eles são`]],
["Frases essenciais","Essere e avere em contexto",[
`Essere#Essere = ser/estar. Atenção: "è" (verbo) ≠ "e" (conjunção "e"). Pronúncia: "è" tem acento aberto.#Sono stanco|Estou cansado;Sei di Roma|Você é de Roma;Lei è la mia amica|Ela é minha amiga;Siamo a casa|Estamos em casa;Siete qui|Vocês estão aqui;Sono felice|Estou feliz`,
`Avere#Avere = ter. O "h" é mudo: ho, hai, ha, hanno. Em italiano diz-se "tenho fome" (ho fame), como em português.#Ho una sorella|Tenho uma irmã;Hai fame?|Você está com fome?;Ha un cane|Ele tem um cachorro;Abbiamo tempo|Temos tempo;Avete sete?|Vocês estão com sede?;Hanno una casa|Eles têm uma casa`,
`Em contexto#Atenção: "caldo" é calor, não "caldo" de comida. Estados físicos usam avere: ho sonno, ho caldo, ho freddo.#Ho sonno|Estou com sono;Ho caldo|Estou com calor;Non ho freddo|Não estou com frio;Dove sei?|Onde você está?;Sono a Roma|Estou em Roma;Ho bisogno di aiuto|Preciso de ajuda`]],
["Pessoas e família","Vocabulário, gênero e artigos básicos",[
`Família#Substantivos femininos costumam terminar em -a, masculinos em -o. Artigo masculino: il; feminino: la.#la madre|a mãe;il padre|o pai;il fratello|o irmão;la sorella|a irmã;il nonno|o avô;la nonna|a avó`,
`Pessoas#Antes de vogal, o artigo vira l': l'amico, l'amica, l'uomo.#l'amico|o amigo;l'amica|a amiga;il bambino|o menino;la bambina|a menina;l'uomo|o homem;la donna|a mulher`,
`Artigos#Indefinidos: un/una (um/uma). Plurais: i (masc.) e le (fem.). Falso cognato: "parenti" = parentes, não pais.#un libro|um livro;una casa|uma casa;il ragazzo|o rapaz;la ragazza|a moça;i figli|os filhos;le sorelle|as irmãs`]],
["No café","Comidas, bebidas e pedidos simples",[
`Bebidas#Cultura: "un caffè" na Itália é um expresso pequeno. Cappuccino costuma ser tomado só de manhã.#un caffè|um café;un'acqua|uma água;un tè|um chá;un succo|um suco;il latte|o leite;una birra|uma cerveja`,
`Comidas#"Cornetto" é o croissant italiano. "Gelato" é sorvete.#il pane|o pão;il cornetto|o croissant;la pizza|a pizza;il formaggio|o queijo;la torta|o bolo;il gelato|o sorvete`,
`Pedidos#"Vorrei" (eu gostaria) é a forma educada de pedir. Pronúncia: "ggi" em "formaggio" soa como "dj"; "gn", em "lasagna", soa como "nh".#Vorrei un caffè|Eu queria um café;Un cappuccino, per favore|Um cappuccino, por favor;Quanto costa?|Quanto custa?;Il conto, per favore|A conta, por favor;Un tavolo per due|Uma mesa para dois;Posso pagare con la carta?|Posso pagar com cartão?`]],
["Vida cotidiana","Números, horários e verbos regulares",[
`Números#Pronúncia: "tre" com r vibrante; "cinque" soa "tchínkue".#uno|um;due|dois;tre|três;quattro|quatro;cinque|cinco;dieci|dez`,
`Horários#Usa-se o artigo plural: "Sono le tre", mas "È mezzogiorno" e "È mezzanotte" no singular.#Che ore sono?|Que horas são?;Sono le tre|São três horas;È mezzogiorno|É meio-dia;È mezzanotte|É meia-noite;A che ora?|A que horas?;Alle otto|Às oito`,
`Verbos#Verbos em -are: eu termina em -o (parlare → parlo). Falso cognato: "abito" = moro, não "hábito".#Parlo italiano|Falo italiano;Mangio la pizza|Como pizza;Bevo un caffè|Bebo um café;Lavoro a Recife|Trabalho em Recife;Abito qui|Moro aqui;Studio ogni giorno|Estudo todo dia`]]
].map((u,ui)=>({t:u[0],d:u[1],l:u[2].map((s,li)=>{const[t,n,w]=s.split('#');return{t,n,k:ui+'-'+li,w:w.split(';').map((x,i)=>{const[it,pt]=x.split('|');return{k:ui+'-'+li+'-'+i,it,pt,c:u[0]}})}})}));
let course='it',account=null,guest=false,authReady=false,authBusy=false,authMode='login',authError='',syncState='local',syncBusy=false,conflict=null;
const COURSES={it:enrichFoundation(ITALIAN_COURSE,'it').concat(buildExpansion('it')),en:enrichFoundation(ENGLISH_COURSE,'en').concat(buildExpansion('en'))};
let U=COURSES.it,V=U.flatMap(u=>u.l.flatMap(l=>l.w)),VK=Object.fromEntries([...V,...VOCABULARY[course]].map(x=>[x.k,x]));
const LANGUAGE={it:{name:'Italiano',target:'italiano',voice:'it-IT',greet:['Buongiorno','Buon pomeriggio','Buonasera'],hello:'Ciao.',bye:'A PRESTO',motto:'Il tuo italiano.'},en:{name:'Inglês',target:'inglês',voice:'en-US',greet:['Good morning','Good afternoon','Good evening'],hello:'Hello.',bye:'SEE YOU SOON',motto:'Your English journey.'}};
const language=()=>LANGUAGE[course];
function setCourse(c){course=c;U=COURSES[c];V=U.flatMap(u=>u.l.flatMap(l=>l.w));VK=Object.fromEntries([...V,...VOCABULARY[course]].map(x=>[x.k,x]));resetLexFilters();}
// ---- ESTADO + PERSISTÊNCIA (IndexedDB) ----
const DEF=()=>({v:1,p:{name:'',lvl:0,goal:'viagens',min:10,theme:'dark',snd:1,rm:0,on:0},xp:0,days:{},done:{},srs:{},fav:{},acc:{},sess:null,last:null});
let S=DEF();
const db=new Promise(r=>{try{const q=indexedDB.open('parlo',1);q.onupgradeneeded=()=>q.result.createObjectStore('kv');q.onsuccess=()=>r(q.result);q.onerror=()=>r(null)}catch(e){r(null)}});
async function localGet(key){const d=await db;if(!d)return;return new Promise(resolve=>{const q=d.transaction('kv').objectStore('kv').get(key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>resolve()})}
async function localPut(key,value){const d=await db;if(!d)return;return new Promise((resolve,reject)=>{const tx=d.transaction('kv','readwrite');tx.objectStore('kv').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
const owner=()=>account?.id||'guest';
const stateKey=(id,lang)=>'state:'+id+':'+lang;
let records={};let saveTimer;
async function save(){
 const id=owner(),lang=course,key=stateKey(id,lang),state=structuredClone(S),old=records[key]||{revision:0};
 const record={...old,state,dirty:true,localVersion:(old.localVersion||0)+1};records[key]=record;
 try{await localPut(key,record)}catch{syncState='error'}
 if(account){syncState=conflict?'conflict':'pending';clearTimeout(saveTimer);saveTimer=setTimeout(()=>syncProgress(),800)}
}
// ---- CORREÇÃO ----
const norm=s=>s.toLowerCase().replace(/[.,!?;:"¿¡]/g,'').replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim();
const flat=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function grade(a,exp){const x=norm(a),y=norm(exp);if(x===y)return{ok:1};if(flat(x)===flat(y))return{ok:0,m:'Atenção aos acentos: eles mudam o sentido (ex.: "è" = é, verbo; "e" = e, conjunção).'};return{ok:0}}
// ---- REVISÃO ESPAÇADA (regras fixas, não é IA) ----
// Acertos seguidos b: próximo intervalo = [1,3,7,14,30] dias[b-1]. Erro: b=0, volta em 10 min.
const IV=[1,3,7,14,30],DAY=864e5;
function upd(k,ok){const e=S.srs[k]||{b:0};e.b=ok?Math.min(e.b+1,5):0;e.due=Date.now()+(ok?IV[e.b-1]*DAY:6e5);S.srs[k]=e}
const due=()=>Object.keys(S.srs).filter(k=>S.srs[k].due<=Date.now());
// ---- ÁUDIO ----
const hasV=()=>'speechSynthesis' in window&&speechSynthesis.getVoices().some(v=>v.lang.toLowerCase().startsWith(language().voice.slice(0,2)));
const aud=()=>S.p.snd&&hasV();
function say(t,slow){if(!aud())return;const u=new SpeechSynthesisUtterance(t);u.lang=language().voice;u.voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(language().voice.slice(0,2)));u.rate=slow?.55:.95;speechSynthesis.cancel();speechSynthesis.speak(u)}
if('speechSynthesis' in window)speechSynthesis.onvoiceschanged=()=>{if(document.activeElement?.tagName!=='INPUT'&&!recognition)render()};
// ---- UTIL ----
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const shuf=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]]}return a};
const td=()=>new Date().toLocaleDateString('sv');
function streak(){let d=new Date(),n=0;if(!S.days[td()])d.setDate(d.getDate()-1);while(S.days[d.toLocaleDateString('sv')]){n++;d.setDate(d.getDate()-1)}return n}
const secs=()=>(S.days[td()]||{s:0}).s;
const nextL=()=>{for(const u of U)for(const l of u.l)if(!S.done[l.k])return[u,l];return[U[0],U[0].l[0]]};
const opts=(x,f)=>shuf([x,...shuf(V.filter(y=>y.k!==x.k&&y[f]!==x[f])).slice(0,3)]).map(y=>y[f]);
// ---- EXERCÍCIOS ----
function mkEx(x,kind){
 const words=x.it.split(' '),multi=words.length>1;
 if(kind==='match'){const g=[x,...shuf(V.filter(y=>y.c===x.c&&y.k!==x.k)).slice(0,3)];return{t:'match',k:x.k,q:'Associe cada item ao significado',ps:g,a:g.map(y=>y.it+' = '+y.pt).join('; '),r:shuf(g.map(y=>y.pt))}}
 if(kind==='listen'&&aud())return{t:'listen',k:x.k,q:'Ouça e escolha a frase correta',a:x.it,o:opts(x,'it'),x:x.pt};
 if(kind==='order'&&multi){let w=shuf(words),n=0;while(w.join(' ')===x.it&&n++<9)w=shuf(w);return{t:'order',k:x.k,q:'Monte a frase: "'+x.pt+'"',a:x.it,w}}
 if(kind==='cloze'&&multi){const i=words.length-1,c=words.slice();c[i]='____';return{t:'cloze',k:x.k,q:'Complete: '+c.join(' ')+'  ("'+x.pt+'")',a:words[i],o:shuf([words[i],...shuf(V.flatMap(y=>y.it.split(' ')).filter(w=>w!==words[i]&&w.length>2)).slice(0,3)])}}
 if(kind==='type')return{t:'type',k:x.k,q:'Traduza para o '+language().target+': "'+x.pt+'"',a:x.it};
 return{t:'choice',k:x.k,q:'Qual é a tradução de "'+x.it+'"?',a:x.pt,o:opts(x,'pt')}}
const KINDS=['choice','order','type','listen','cloze','match'];
function startLesson(k){
 if(S.sess&&S.sess.lk===k){location.hash='#/lic';return}
 const l=U.flatMap(u=>u.l).find(l=>l.k===k);
 S.sess={lk:k,ex:l.w.map((x,i)=>mkEx(x,KINDS[i%6])),i:0,ok:0,intro:0,sec:0,t:Date.now()};save();location.hash='#/lic'}
function startRev(){const ks=due().slice(0,10);if(!ks.length)return;
 S.sess={lk:'rev',ex:ks.map((k,i)=>mkEx(VK[k],i%2?'type':'choice')),i:0,ok:0,intro:1,sec:0,t:Date.now()};save();location.hash='#/lic'}
let st={};
function finish(){const s=S.sess,sec=s.sec,xp=s.ok*10,d=td();
 if(s.pl){let su=U.findIndex((_,i)=>((s.pu&&s.pu[i])||0)<2);if(su<0)su=U.length-1;S.last={pl:1,ok:s.ok,n:s.ex.length,su};S.sess=null;save();location.hash='#/fim';return}
 const e=S.days[d]||{xp:0,s:0};e.xp+=xp;e.s+=sec;S.days[d]=e;S.xp+=xp;
 if(s.lk!=='rev')S.done[s.lk]=(S.done[s.lk]||0)+1;
 S.last={lk:s.lk,ok:s.ok,n:s.ex.length,xp,sec};S.sess=null;save();location.hash='#/fim'}
function check(){if(st.res)return;const s=S.sess,e=s.ex[s.i];let a=e.t==='order'?st.pick.join(' '):e.t==='type'?document.getElementById('ti').value:st.sel,g=e.t==='match'?{ok:st.m.x?0:1}:grade(a,e.a);
 st.res=g;s.feedback=JSON.parse(JSON.stringify(st));if(g.ok)s.ok++;if(s.pl){const u=e.k.split('-')[0];s.pu=s.pu||{};s.pu[u]=(s.pu[u]||0)+g.ok}else upd(e.k,g.ok);const A=S.acc[e.t]||[0,0];A[0]+=g.ok;A[1]++;S.acc[e.t]=A;save();render()}
function next(){const s=S.sess;if(!st.res)return;s.i++;delete s.feedback;st={};if(s.i>=s.ex.length)finish();else{save();render()}}
function lessonView(){const s=S.sess;if(!s){location.hash='#/';return''}
 if(!s.intro){const l=U.flatMap(u=>u.l).find(l=>l.k===s.lk);
  return`<div class="row"><h1>${esc(l.t)}</h1><a class="btn s" href="#/">Sair</a></div><div class="card"><p>${esc(l.n)}</p></div><div class="card">${l.w.map(x=>`<div class="row"><p><b>${esc(x.it)}</b><br><span class="mu">${esc(x.pt)}</span></p><span><button class="btn s" aria-pressed="${!!S.fav[x.k]}" aria-label="Salvar ${esc(x.it)}" onclick="S.fav['${x.k}']=!S.fav['${x.k}'];save();render()">${S.fav[x.k]?'★':'☆'}</button> <button class="btn s" aria-label="Ouvir ${esc(x.it)}" onclick="say(${JSON.stringify(x.it).replace(/"/g,'&quot;')})">Ouvir</button></span></div>`).join('')}${aud()?'':'<p class="mu">Sem voz italiana neste navegador: as atividades usam texto.</p>'}</div><button class="btn w" onclick="S.sess.intro=1;save();render()">Começar</button>`}
 const e=s.ex[s.i],r=st.res,pct=s.i/s.ex.length*100;
 let body='';
 const O=e.o?e.o.map(o=>`<button class="opt" aria-pressed="${st.sel===o}" ${r?'disabled':''} onclick="st.sel=this.dataset.v;render()" data-v="${esc(o)}">${esc(o)}</button>`).join(''):'';
 if(e.t==='listen')body=`<button class="btn s" onclick="say(${JSON.stringify(e.a).replace(/"/g,'&quot;')})">Ouvir</button> <button class="btn s" onclick="say(${JSON.stringify(e.a).replace(/"/g,'&quot;')},1)">Mais devagar</button>${O}`;
 else if(e.t==='order'){st.pick=st.pick||[];body=`<div class="ans" aria-label="Sua frase">${st.pick.map((w,i)=>`<button class="tile" ${r?'disabled':''} onclick="st.pick.splice(${i},1);render()">${esc(w)}</button>`).join('')}</div>`+e.w.map((w,i)=>st.pick.includes(w+'\u0001'+i)?'':`<button class="tile" ${r?'disabled':''} onclick="st.pick.push(this.dataset.w);render()" data-w="${esc(w)}">${esc(w)}</button>`).join('')}
 else if(e.t==='type')body=`<label for="ti">Sua resposta</label><input type="text" id="ti" autocomplete="off" autocapitalize="off" ${r?'disabled':''} onkeydown="if(event.key==='Enter'&&!${!!r})check()" value="${esc(st.ti||'')}" oninput="st.ti=this.value;document.getElementById('vb').disabled=!this.value.trim()">`;
 else if(e.t==='match'){st.m=st.m||{d:[],l:null,x:0};const m=st.m,b=(t,v,s)=>`<button class="tile" style="width:100%;margin:4px 0" ${m.d.includes(v)||r?'disabled':''} ${s?`aria-pressed="${m.l===v}"`:''} onclick="mt(${s?0:1},this.dataset.v)" data-v="${esc(v)}">${m.d.includes(v)?'✓ ':''}${esc(t)}</button>`;body='<div class="g2"><div>'+e.ps.map(p=>b(p.it,p.pt,1)).join('')+'</div><div>'+e.r.map(t=>b(t,t,0)).join('')+'</div></div><p class="mu">Erros: '+m.x+'</p>'}else body=O;
 if(e.t==='order'){const used=[...st.pick];body=`<div class="ans" aria-label="Sua frase">${st.pick.map((w,i)=>`<button class="tile" ${r?'disabled':''} onclick="st.pick.splice(${i},1);render()">${esc(w)}</button>`).join('')}</div>`+e.w.filter(w=>{const i=used.indexOf(w);if(i>-1){used.splice(i,1);return false}return true}).map(w=>`<button class="tile" ${r?'disabled':''} onclick="st.pick.push(this.dataset.w);render()" data-w="${esc(w)}">${esc(w)}</button>`).join('')}
 const ready=e.t==='match'?(st.m&&st.m.d.length===e.ps.length):e.t==='order'?st.pick.length:e.t==='type'?(st.ti||'').trim():st.sel;
 const fb=r?`<div class="fb ${r.ok?'ok':'no'} pop" role="status"><b>${r.ok?'✓ Correto!':'✗ Quase lá'}</b><p>Resposta esperada: <b>${esc(e.a)}</b></p>${r.m?`<p>${esc(r.m)}</p>`:''}<p class="mu">${esc(VK[e.k].it)} = ${esc(VK[e.k].pt)}. Erros voltam na revisão em breve.</p><button class="btn s" aria-pressed="${!!S.fav[e.k]}" onclick="tg('${e.k}')">${S.fav[e.k]?'★ Salvo':'☆ Salvar para ver depois'}</button></div>`:'';
 return`<div class="row"><a class="btn s" href="#/" aria-label="Sair e retomar depois">Sair</a><div class="bar" style="flex:1" role="progressbar" aria-valuenow="${Math.round(pct)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><span class="mu">${s.i+1}/${s.ex.length}</span></div><h2 style="margin-top:20px">${esc(e.q)}</h2>${body}${fb}${r?`<button class="btn w" onclick="next()">Continuar</button>`:`<button class="btn w" id="vb" ${ready?'':'disabled'} onclick="check()">Verificar</button>`}`}
