async function changePassword(event){event.preventDefault();const f=event.target,button=f.querySelector('button'),message=document.getElementById('password-message');button.disabled=true;try{if(f.elements.password.value!==f.elements.confirm.value)throw Error('As senhas novas não coincidem.');await api('/api/auth/password',{method:'POST',body:JSON.stringify({currentPassword:f.elements.current.value,password:f.elements.password.value})});f.reset();message.textContent='Senha alterada. As outras sessões foram encerradas.'}catch(e){message.textContent=e.message}finally{button.disabled=false}}
